module schemas

import vsupport
import models
import json2
import time

pub struct TaskStatusUpdate {
pub:
	action string
	reason ?string
}

pub fn task_status_update_from_json(m map[string]json2.Any) !TaskStatusUpdate {
	action := vsupport.jstr(m, 'action')
	vsupport.validate_pattern(action, '^(approve|cancel)$', 'action')!
	reason_raw := vsupport.jstr(m, 'reason')
	mut reason := ?string(none)
	if reason_raw != '' {
		if reason_raw.len > 1000 {
			return vsupport.validation_error('reason must be at most 1000 characters long')
		}
		reason = reason_raw
	}
	return TaskStatusUpdate{
		action: action
		reason: reason
	}
}

pub fn task_summary_to_json(t &models.Task) map[string]json2.Any {
	mut out := vsupport.jmap()
	out['id'] = json2.Any(t.id.str())
	out['short_id'] = json2.Any(t.short_id)
	out['title'] = json2.Any(t.title)
	out['status'] = json2.Any(t.status)
	if v := t.task_category {
		out['task_category'] = json2.Any(v)
	}
	if v := t.risk_level {
		out['risk_level'] = json2.Any(v)
	}
	out['created_at'] = json2.Any(vsupport.isoformat(t.created_at))
	out['updated_at'] = json2.Any(vsupport.isoformat(t.updated_at))
	if v := t.started_at {
		out['started_at'] = json2.Any(vsupport.isoformat(v))
	}
	if v := t.completed_at {
		out['completed_at'] = json2.Any(vsupport.isoformat(v))
	}
	if v := t.actual_cost_usd {
		out['actual_cost_usd'] = json2.Any(v)
	}
	if v := t.total_tokens_used {
		out['total_tokens_used'] = json2.Any(v)
	}
	out['requires_approval'] = json2.Any(t.requires_approval)
	return out
}

